    row_cuts = [r for r in range(h) if len(set(grid[r])) == 1]
    col_cuts = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1]

    def intervals(size, cuts):
        edges = [-1] + cuts + [size]
        return [(edges[i] + 1, edges[i + 1]) for i in range(len(edges) - 1)]

    row_tiles = intervals(h, row_cuts)
    col_tiles = intervals(w, col_cuts)
    tiles = [(r0, r1, c0, c1) for r0, r1 in row_tiles for c0, c1 in col_tiles]

    # Pick the tile containing the template, then repeat its contents in each tile.
    source = max(
        tiles,
        key=lambda t: sum(
            grid[r][c] != background
            for r in range(t[0], t[1])
            for c in range(t[2], t[3])
        )
    )
    sr0, sr1, sc0, sc1 = source
    out = [row[:] for row in grid]

    for r0, r1 in row_tiles:
        for c0, c1 in col_tiles:
            for r in range(r0, r1):
                for c in range(c0, c1):
                    sr = sr0 + (r - r0)
                    sc = sc0 + (c - c0)
                    if sr < sr1 and sc < sc1:
                        out[r][c] = grid[sr][sc]
    return out
